window.CURATION={"exhibition": {"title": "北京的三十种面孔", "subtitle": "地图如何选择一座城", "thesis": "每张地图都在选择：什么被看见，什么被留下。", "entryQuestion": "同一座北京，为什么会有三十种模样？", "entryIntroduction": "从一条中轴到一声鸟鸣，从院落的内部到画面的留白，三十幅作品用不同规则重新组织北京。沿着秩序、生活与想象走过三间展厅，看看每种画法让什么变得清楚，又把什么留给了你的想象。", "exitQuestion": "如果由你画北京，你会保留什么，又会承认什么还不知道？", "disclaimerShort": "所有地图皆为AI创作，请勿与实际地理空间对应。", "interpretationNote": "展陈文字依据画面进行解读，不代表作者原始自述。图中的地名、距离、布局、材质与感官信息均不能据此视为事实记录。", "preservation": ["保留全部30件作品及编号", "保留原始完整图像与长宽比，不裁掉图内标题、图例、边框或脚注", "可以调整展墙展示尺寸，不改变原图", "展开阅读不替换原作，实验区与原作清楚分开"]}, "halls": [{"id": "order", "number": "01", "title": "城的秩序", "subtitle": "一条线，还是许多条路？", "wallLabel": "找到一条线，也看看线外的北京。", "introduction": "点、线、面与网格，把复杂的城市变成可读的图像。一条中轴让视线集中，许多街巷让道路分叉。先找出每张图的规则，再看看同一座城怎样随着规则改变。", "question": "你先看到的是一座城，还是组织这座城的规则？", "featuredMapIds": ["02", "24"], "clusters": [{"title": "一线与多路", "mapIds": ["02", "24", "21"], "role": "主对照组；02与24可同时看见，21在旁承接共同记录的主题"}, {"title": "点怎样成为群", "mapIds": ["01", "04"], "role": "紧邻双联组；提示比较单点与聚集"}, {"title": "换个尺度看", "mapIds": ["03", "09", "22"], "role": "三联组；从面与城乡过渡到投影视角"}, {"title": "把城市分格", "mapIds": ["20", "29"], "role": "紧邻双联组；比较不同离散单元"}], "transition": "当线变成一条可以走的街，地图就接近了生活。"}, {"id": "life", "number": "02", "title": "街巷的生活", "subtitle": "地图装得下日常吗？", "wallLabel": "从屋顶走进去，让看不见的生活现身。", "introduction": "院落有里面和外面，水岸有相连和分隔，日常还有声音、气味与味道。这一厅从可以看见的空间出发，尝试把身体记得的北京也放进地图。", "question": "离开地名，你还能用什么认出一个地方？", "featuredMapIds": ["15", "11"], "clusters": [{"title": "里面与之间", "mapIds": ["15", "13"], "role": "15为主作，13承接开合与连接关系"}, {"title": "看不见的日常", "mapIds": ["11", "19", "23"], "role": "感官三联组；11为主作，声、嗅、味共同观看"}, {"title": "在水边停一会儿", "mapIds": ["07", "10", "26", "27"], "role": "四件节奏较紧的水岸组；用一段组签取代四篇长说明"}, {"title": "回望这座城", "mapIds": ["05"], "role": "转角单件；为从身体经验回到整体观看留出停顿"}], "transition": "地图能装进感受，也能换一种材料与想象。"}, {"id": "imagination", "number": "03", "title": "想象的北京", "subtitle": "换一种画法，换一种城市", "wallLabel": "换一种材料，给未知留一个位置。", "introduction": "仿古、水墨、针线与纸笔，让北京拥有不同的表情。想象可以打开新的观看方式，留白则提醒我们表达的边界。最后，把画什么、怎么画的问题交还给你。", "question": "一张地图还可以改变什么，又应该坦白什么？", "featuredMapIds": ["25", "18"], "clusters": [{"title": "换一种材料", "mapIds": ["06", "25", "30"], "role": "25为主作；仿古、织物意象与纸笔风格形成材料对话"}, {"title": "换一种可能", "mapIds": ["08", "12", "17", "28"], "role": "四件想象组；光暗与感受等不同命题并置，避免声称真实环境数据"}, {"title": "图外还有什么", "mapIds": ["14", "18", "16"], "role": "18为结尾主作；14提出表述边界，16接续观众共绘邀请"}], "transition": "带走一个问题：你的地图，会让谁的北京被看见？"}], "stops": [{"stop": 1, "mapId": "02", "hallId": "order", "title": "一条线，把视线聚拢", "wallLabel": "沿红线看，也向红线两侧看。", "narration": "先顺着画面中央的红线看，再移向两侧淡淡的街巷。门楼与院落被一线串起，城市因而显得整齐。试着暂时忽略红线，你的目光还会走同一条路吗？", "visitorQuestion": "如果拿走红线，你第一眼会停在哪里？", "takeaway": "地图的秩序，也在安排观看的顺序。", "lookAt": "中央贯穿画面的红线，以及两侧较淡的街巷", "fullReading": "红线、连续的建筑节点与纵向构图共同引导目光。周边街巷虽然丰富，色彩却较轻，容易退到背景。这里可把“中轴”读作一种视觉组织方法：它让多个地方形成一条清楚的阅读线索。此解读只描述画面的构图，不用图中位置、距离或文字核实真实城市。", "pixelEvidence": ["画面中央可见连续红色竖线", "轴线两侧街巷以较淡线条呈现", "标注与建筑节点沿纵向分布"], "nextTransition": "一条主线之外，一座城还有多少条可以选择的路？", "audio": "data:audio/mpeg;base64,"}, {"stop": 2, "mapId": "24", "hallId": "order", "title": "许多条路，留下选择", "wallLabel": "一座街巷，两种网络画法。", "narration": "红色路径穿过街巷，青色圆点与金色连线留下更多分岔。再看右下角，建筑消失了，连接仍在。把两处相同的结构找出来，看看地图究竟保留了什么。", "visitorQuestion": "没有建筑细节，你还能认出哪一段连接？", "takeaway": "删去外貌，也能保留关系。", "lookAt": "大图中的红色路线与右下角简化网络", "fullReading": "这件作品把街巷景象与一个简化网络放在同一画面。圆点标示节点，连线标示连接，红色突出一条路径。右下角的小图减少建筑、水面与树木的细节，使观看转向“谁与谁相连”。与02同时看，一件集中视线，一件展示分岔；它们为读城选择了不同规则。", "pixelEvidence": ["底部图例分别标示节点、连接、路径", "右下角有标记A至F的抽象网络", "大图中有青色节点、金色连线与红色路径"], "compareWithMapId": "02", "comparePrompt": "两幅图分别怎样引导你的目光：沿一条线前行，还是在岔路中选择？", "nextTransition": "沿着街巷走到一扇门前，地图能不能带我们进去？", "audio": "data:audio/mpeg;base64,"}, {"stop": 3, "mapId": "15", "hallId": "life", "title": "把屋顶打开，看见生活", "wallLabel": "屋顶之下，还有另一张地图。", "narration": "画面把部分屋顶与房间打开，让院心、家具和出入口一起出现。下方两张小图又把同一院落分别盖上、打开。请沿门口走到树下，想一想视线与脚步有什么不同。", "visitorQuestion": "从门口到院心，哪一处让你想停下来？", "takeaway": "改变看法，也会改变空间里被看见的生活。", "lookAt": "院心的树、右下方入口、底部屋顶视图与内部空间两张小图", "fullReading": "鸟瞰让人看见院落的整体，打开的房间又呈现桌椅、床与陈设。底部的屋顶视图和内部空间把这两种观看并排给出。它们提示：外部轮廓与内部生活可以是不同层次的信息。互动模型应作为围合关系的概念演示，不声称复原某座真实四合院，也不覆盖或改动原作。", "pixelEvidence": ["中央院心有开花的树与石桌凳", "部分房间敞开并可见家具", "底部并排标为屋顶视图与内部空间"], "interactionPrompt": "先比较盖上与打开的两张小图，再选择是否进入空间实验。", "nextTransition": "看见房间以后，试着想起那些画面本身发不出的声音。", "audio": "data:audio/mpeg;base64,"}, {"stop": 4, "mapId": "11", "hallId": "life", "title": "看见听不见的城市", "wallLabel": "这些圆圈，把什么声音放进了地图？", "narration": "鸟鸣、水声、人声与车流，被画成四种圆形符号，放在树、水岸、胡同与道路旁。先找一个符号，再看它周围的细节：同一张安静的图，能在你的记忆里响起来吗？", "visitorQuestion": "哪一种声音最能让你认出熟悉的地方？", "takeaway": "地图也能组织经验，未必只标记位置。", "lookAt": "四种带同心圆的声音图标，以及底部对应的小画面", "fullReading": "四类声音使用颜色与图形区分，底部小画面把符号重新连回具体景象：鸟、划水动作、交谈者与车辆。读图的线索由“在那里”转向“在那里会感到什么”。这里表现的是一种声景想象，圆圈并非实测声场，颜色与大小不能用来判断真实音量或传播距离。", "pixelEvidence": ["四类图标在底部标为鸟鸣、水声、人声、车流", "地图与底部小画面复用相应颜色", "图标周围有同心圆"], "interactionPrompt": "静默观察即可完成；若后续添加音效，需明确为示意，并提供等价文字和独立开关。", "nextTransition": "声音可以变成符号，街巷还能变成什么材料？", "audio": "data:audio/mpeg;base64,"}, {"stop": 5, "mapId": "25", "hallId": "imagination", "title": "街巷变成针线", "wallLabel": "路像线，水像针脚：这还是地图吗？", "narration": "街道变成绳线，湖泊像密密的针脚，边缘还留下散开的线头。请从蓝色水面找到红色院落，再问自己：当城市被画成一块织物，我们读到的关系发生了什么变化？", "visitorQuestion": "让你认出地图的，是材料、地名，还是它们之间的关系？", "takeaway": "改变材料的想象，可以改变读城的感受。", "lookAt": "蓝色针脚意象、金色道路绳线、边缘线头和右下方线团", "fullReading": "画面借用针线、绳结与织物边缘来表达水面、道路和院落。右下方的针与线团强化了这种材料联想，图例也以针法意象解释符号。这是AI生成的织物地图图像，不能据此声称存在一件实物刺绣。它邀请我们注意：地图的符号不仅传递关系，也会唤起触感与情绪。", "pixelEvidence": ["地图外缘有外伸的散线", "右下方可见针与三团彩线", "道路、水域、院落被画成不同针线意象"], "nextTransition": "画面可以如此丰富，也可以把不知道的地方明确留下。", "audio": "data:audio/mpeg;base64,"}, {"stop": 6, "mapId": "18", "hallId": "imagination", "title": "把未知留在图上", "wallLabel": "留白里没有画出，不等于那里不存在。", "narration": "四块虚线围出的留白标着待记录，画面边缘还有淡去的范围外。它们和已画出的街区同时存在。最后，选一块留白：如果继续这张图，你会先去了解什么，而不是急着填满？", "visitorQuestion": "属于你的地图里，哪一处值得先倾听、再画下？", "takeaway": "承认未知，也是地图表达的一部分。", "lookAt": "四块虚线边界内的待记录，以及外缘较淡的范围外", "fullReading": "右下角图例将画面分为示例已记录、待记录与范围外三类。不同处理使“还不知道”和“没有纳入”也变成可读的信息。图中的空白是艺术设定，并不证明北京存在这些真实的数据空缺。以此结束导览，是把判断交回观众：下一张地图可以从补充信息开始，也可以先为他人的经验留出位置。", "pixelEvidence": ["四个内部留白区以虚线边界标注待记录", "画面外缘出现范围外字样", "右下角图例区分三种状态"], "compareWithMapId": "25", "comparePrompt": "一幅把街巷织得密密实实，一幅刻意留出空白；两种选择分别让你注意什么？", "nextTransition": "回到共绘作品16，想一想你愿意补充的一条经验。", "audio": "data:audio/mpeg;base64,"}], "pairs": [{"mapIds": ["02", "24"], "title": "一线与多路", "question": "一幅集中视线，一幅提供分岔；你的目光怎样改变？"}, {"mapIds": ["01", "04"], "title": "点与群", "question": "加上分组边界以后，你先看到单个园林，还是它们组成的一群？"}, {"mapIds": ["03", "09"], "title": "向内看与向外走", "question": "一幅分层向院落靠近，一幅从城向田展开；尺度改变了什么？"}, {"mapIds": ["20", "29"], "title": "一块与一格", "question": "六边形局部和方形像元，分别怎样切分连续的画面？"}, {"mapIds": ["21", "22"], "title": "一片街巷与一个世界", "question": "从街巷到世界，哪些细节还值得保留？"}, {"mapIds": ["05", "11"], "title": "眼前与耳边", "question": "视线范围与声音符号，分别让你注意城市的哪一部分？"}, {"mapIds": ["15", "13"], "title": "打开与连接", "question": "一幅打开房间，一幅增加桥梁；空间关系怎样因此变得可见？"}, {"mapIds": ["07", "10"], "title": "简笔与细描", "question": "水面周边的细节增多后，三海的形状更清楚，还是更难辨认？"}, {"mapIds": ["19", "23"], "title": "鼻尖与舌尖", "question": "哪种气味或滋味，会让你立刻想起一个地方？"}, {"mapIds": ["26", "27"], "title": "水岸与街区", "question": "一幅展开城市水岸，一幅突出院落阵列；水怎样参与各自的构图？"}, {"mapIds": ["06", "30"], "title": "仿古与纸笔", "question": "边框、笔触与页边小图，怎样改变你对地图的阅读期待？"}, {"mapIds": ["08", "12"], "title": "花园与能量", "question": "绿色景观在两幅作品里，分别承担怎样的想象？"}, {"mapIds": ["17", "28"], "title": "光线与心情", "question": "明暗和颜色，怎样使同一个地点带上不同感受？"}, {"mapIds": ["14", "25"], "title": "纸与布的想象", "question": "纸页与针线的意象，怎样让地图与城市发生新的关系？"}, {"mapIds": ["16", "18"], "title": "待你填写与尚未记录", "question": "两种留白分别邀请你做什么：补充经验，还是承认未知？"}, {"mapIds": ["25", "18"], "title": "织满与留白", "question": "一幅细密地编织，一幅明确地留空；它们分别让什么被看见？"}], "sources": [{"title": "Victoria and Albert Museum, Writing Gallery Text at the V&A", "url": "https://www.vam.ac.uk/blog/wp-content/uploads/VA_Gallery-Text-Writing-Guidelines_online_Web.pdf"}, {"title": "The Museum of Modern Art, Meet Me Practice: Foundations for Engagement with Art", "url": "https://www.moma.org/visit/accessibility/meetme/practice/foundations.html"}, {"title": "Smithsonian · 无障碍展览设计指南", "url": "https://www.sifacilities.si.edu/sites/default/files/Files/Accessibility/accessible-exhibition-design1.pdf"}, {"title": "V&A Dundee · 展览设计与展品之间的关系", "url": "https://www.vam.ac.uk/dundee/articles/designing-hello-robot"}], "study": {"islands": [{"title": "把城市重新编排", "subtitle": "02 轴线｜24 网络｜20 六边形局部｜29 方格像元", "mapIds": ["02", "24", "20", "29"], "prompt": "先沿02的红线走，再在24的分岔处停下；把20底部的六边形与29右下角的方格放在一起看。线、连接和单元各自突出了什么，又让哪些细节退到背景？"}, {"title": "身体怎样记住城市", "subtitle": "05 眼前｜11 耳边｜19 鼻尖｜23 舌尖", "mapIds": ["05", "11", "19", "23"], "prompt": "在四幅作品中，各找一种表达感官的画法：扇形视域、声音符号、气味线索与食物小画面。选一处让你想起自身经验的细节：不用地名，你会怎样向别人描述这个地方？"}, {"title": "地图的四种表情", "subtitle": "06 仿古图饰｜25 针线意象｜28 水墨情绪｜30 纸笔风格", "mapIds": ["06", "25", "28", "30"], "prompt": "比较四幅图的边缘和局部：装饰边框、散开的线头、情绪色层、页边小稿怎样改变读图的感觉？如果把一张图换成另一种画法，你最想保留什么？这些都是AI图像中的风格与材料意象。"}], "details": [{"mapId": "02", "hotspotIndex": 0, "title": "红线遇见院落", "caption": "取自02号作品原图局部。金色屋顶、层层围合与红色中线在这里相遇，把目光收向中央。先追随红线，再看两侧较淡的街巷：假如忽略这条线，你会先注意哪里？"}, {"mapId": "02", "hotspotIndex": 1, "title": "疏密之间的停顿", "caption": "建筑的密与广场的疏在红线两侧形成节奏。比较另一块放大板，观察留白怎样改变阅读。"}, {"mapId": "15", "hotspotIndex": 2, "title": "屋顶退开以后", "caption": "取自15号作品下方右侧小图。屋顶让开，家具、房间与院心同时进入视线。顺着出入口看进去：哪一种空间关系，只有在这个打开的视角里才容易发现？这是画中的展开方式。"}, {"mapId": "11", "hotspotIndex": 0, "title": "声音长出形状", "caption": "取自11号作品左上方局部。鸟的形象与向外扩散的圆圈，让看不见的声音拥有了图形。只看这些线，你会想到怎样的声音？它们表达声景想象，不是现场录音或声学测量。"}, {"mapId": "17", "hotspotIndex": 1, "title": "明暗交界处", "caption": "取自17号作品中央通路局部。浅金与深蓝在同一幅画中并置，路与树木因明暗而出现不同的观看节奏。你的目光更愿意在哪一侧停留？这是光影叙事，不是真实日照模拟。"}, {"mapId": "25", "hotspotIndex": 0, "title": "水面变成针脚", "caption": "取自25号作品蓝色水面局部。蓝色线束与浅色网格交织，纹理代替了平涂色块。沿着这些线看一遍：材料的方向感怎样改变你对水面的感受？针线是画面意象，不代表实物刺绣。"}]}};